INSERT INTO dialogue_role (id,lesson_id,code,name_vi,name_ja,description,voice_code) SELECT 6400000000+dr.id,6000001007,dr.code,dr.name_vi,dr.name_ja,dr.description,dr.voice_code FROM dialogue_role dr WHERE dr.lesson_id=@dialogue_src_n4 ON DUPLICATE KEY UPDATE name_vi=VALUES(name_vi),name_ja=VALUES(name_ja),description=VALUES(description),voice_code=VALUES(voice_code);
INSERT INTO lesson_section (id,lesson_id,title,section_type,order_index) SELECT DISTINCT 6400000000+ls.id,6000001007,ls.title,ls.section_type,100+ls.order_index FROM lesson_section ls JOIN content_item ci ON ci.section_id=ls.id JOIN dialogue_line_detail d ON d.content_item_id=ci.id WHERE ls.lesson_id=@dialogue_src_n4 ON DUPLICATE KEY UPDATE title=VALUES(title),order_index=VALUES(order_index);
INSERT INTO content_item (id,section_id,content_type,topic_tag_id,title,content,translated_text,order_index) SELECT 6400000000+ci.id,6400000000+ci.section_id,ci.content_type,ci.topic_tag_id,ci.title,ci.content,ci.translated_text,ci.order_index FROM content_item ci JOIN lesson_section ls ON ls.id=ci.section_id JOIN dialogue_line_detail d ON d.content_item_id=ci.id WHERE ls.lesson_id=@dialogue_src_n4 ON DUPLICATE KEY UPDATE title=VALUES(title),content=VALUES(content),translated_text=VALUES(translated_text),order_index=VALUES(order_index);
INSERT INTO dialogue_line_detail (content_item_id,dialogue_role_id,scene_code,bubble_side,bubble_x,bubble_y) SELECT 6400000000+d.content_item_id,CASE WHEN d.dialogue_role_id IS NULL THEN NULL ELSE 6400000000+d.dialogue_role_id END,d.scene_code,d.bubble_side,d.bubble_x,d.bubble_y FROM dialogue_line_detail d JOIN content_item ci ON ci.id=d.content_item_id JOIN lesson_section ls ON ls.id=ci.section_id WHERE ls.lesson_id=@dialogue_src_n4 ON DUPLICATE KEY UPDATE dialogue_role_id=VALUES(dialogue_role_id),scene_code=VALUES(scene_code),bubble_side=VALUES(bubble_side);
INSERT INTO dialogue_line_chunk (id,content_item_id,order_index,surface,meaning_vi) SELECT 6400000000+c.id,6400000000+c.content_item_id,c.order_index,c.surface,c.meaning_vi FROM dialogue_line_chunk c JOIN content_item ci ON ci.id=c.content_item_id JOIN lesson_section ls ON ls.id=ci.section_id WHERE ls.lesson_id=@dialogue_src_n4 ON DUPLICATE KEY UPDATE surface=VALUES(surface),meaning_vi=VALUES(meaning_vi);
INSERT INTO content_audio (id,owner_type,owner_id,voice_code,audio_url,merged_url,start_ms,end_ms) SELECT 6400000000+a.id,a.owner_type,6400000000+a.owner_id,a.voice_code,a.audio_url,a.merged_url,a.start_ms,a.end_ms FROM content_audio a JOIN content_item ci ON a.owner_type='CONTENT_ITEM' AND ci.id=a.owner_id JOIN dialogue_line_detail d ON d.content_item_id=ci.id JOIN lesson_section ls ON ls.id=ci.section_id WHERE ls.lesson_id=@dialogue_src_n4 ON DUPLICATE KEY UPDATE audio_url=VALUES(audio_url),merged_url=VALUES(merged_url);
