-- BEGIN sql/seeds/learning_owned_sekai_n4_core.sql SHA256 6d7e70f9fb1661b1a0a21c3e04d31da559adec977fd95c1a9a5eda9e3e766dc2
-- [JLAS-W0108] Copy Sekai N4 into the task-owned Learning namespace.
-- Source book id=2 and every source-team row are read-only. Rehearse on a
-- separately selected scratch DB before any apply to a populated DB.
-- ID range 4,000,000 + source ID is reserved for this exact copy. The source
-- book remains DRAFT; the independently owned copy is PUBLISHED for Learning.
-- This does not add Reading/Listening activities to GOAL_LEARNING or retag
-- Smart Test Kanji. Those are separate release gates.

DELIMITER $$
DROP PROCEDURE IF EXISTS jlas_assert_owned_n4_source$$
CREATE PROCEDURE jlas_assert_owned_n4_source()
BEGIN
  IF (SELECT COUNT(*) FROM textbook WHERE id=2 AND jlpt_level='N4'
      AND title='Sekai N4 — Giáo trình tiếng Nhật') <> 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unexpected Sekai N4 source book';
  END IF;
  IF (SELECT COUNT(*) FROM lesson l JOIN unit u ON u.id=l.unit_id
      WHERE u.textbook_id=2) <> 25 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sekai N4 lesson count drift';
  END IF;
  IF EXISTS (SELECT 1 FROM textbook WHERE id=4000002
      AND source_code <> 'LP-OWNED-SEKAI-N4-CORE') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Owned N4 textbook ID collision';
  END IF;
  IF EXISTS (SELECT 1 FROM textbook WHERE source_code='LP-OWNED-SEKAI-N4-CORE'
      AND id <> 4000002) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Owned N4 textbook code collision';
  END IF;
END$$
DELIMITER ;
CALL jlas_assert_owned_n4_source();
DROP PROCEDURE jlas_assert_owned_n4_source;

START TRANSACTION;
  is_learning_path_source,thumbnail_url,thumbnail_kanji,theme_color)
SELECT 4000002,'LP-OWNED-SEKAI-N4-CORE',CONCAT('Learning N4 — ',title),
  'Bản sao task-owned từ Sekai N4; nguồn giữ nguyên DRAFT.',jlpt_level,
  'PUBLISHED',version,1,thumbnail_url,thumbnail_kanji,theme_color
FROM textbook WHERE id=2
ON DUPLICATE KEY UPDATE id=VALUES(id);

SELECT 4000000+u.id,4000002,CONCAT('LP-OWNED-U-',u.id),
  u.title,u.description,u.order_index
FROM unit u WHERE u.textbook_id=2
ON DUPLICATE KEY UPDATE id=VALUES(id);

  order_index,estimated_minutes,lesson_type,skill,situation_tag,is_review,status)
SELECT 4000000+l.id,4000000+l.unit_id,CONCAT('LP-OWNED-L-',l.id),
  l.knowledge_tag_id,l.title,l.description,l.order_index,l.estimated_minutes,
  l.lesson_type,l.skill,l.situation_tag,l.is_review,'PUBLISHED'
FROM lesson l JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=2
ON DUPLICATE KEY UPDATE id=VALUES(id);

SELECT 4000000+lt.lesson_id,lt.tag_id FROM lesson_tag lt
JOIN lesson l ON l.id=lt.lesson_id JOIN unit u ON u.id=l.unit_id
WHERE u.textbook_id=2
ON DUPLICATE KEY UPDATE lesson_id=VALUES(lesson_id);

SELECT 4000000+lk.id,4000000+lk.lesson_id,lk.kanji_id,lk.order_index
FROM lesson_kanji lk JOIN lesson l ON l.id=lk.lesson_id
JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=2
ON DUPLICATE KEY UPDATE id=VALUES(id);

SELECT 4000000+ls.id,4000000+ls.lesson_id,ls.title,ls.section_type,ls.order_index
FROM lesson_section ls JOIN lesson l ON l.id=ls.lesson_id
JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=2
ON DUPLICATE KEY UPDATE id=VALUES(id);

SELECT 4000000+gp.id,4000000+gp.lesson_id,gp.tag_id,gp.pattern,gp.meaning,
  gp.example,gp.note,gp.order_index
FROM grammar_point gp JOIN lesson l ON l.id=gp.lesson_id
JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=2
ON DUPLICATE KEY UPDATE id=VALUES(id);

  title,content,translated_text,order_index)
SELECT 4000000+ci.id,4000000+ci.section_id,ci.content_type,
  CASE WHEN ci.grammar_point_id IS NULL THEN NULL ELSE 4000000+ci.grammar_point_id END,
  ci.topic_tag_id,ci.title,ci.content,ci.translated_text,ci.order_index
FROM content_item ci JOIN lesson_section ls ON ls.id=ci.section_id
JOIN lesson l ON l.id=ls.lesson_id JOIN unit u ON u.id=l.unit_id
WHERE u.textbook_id=2
ON DUPLICATE KEY UPDATE id=VALUES(id);

  learning_example_ja,learning_example_vi)
SELECT 4000000+cv.content_item_id,cv.vocabulary_id,cv.learning_meaning_vi,
  cv.learning_example_ja,cv.learning_example_vi
FROM content_vocabulary cv JOIN content_item ci ON ci.id=cv.content_item_id
JOIN lesson_section ls ON ls.id=ci.section_id JOIN lesson l ON l.id=ls.lesson_id
JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=2
ON DUPLICATE KEY UPDATE content_item_id=VALUES(content_item_id);

SELECT 4000000+dr.id,4000000+dr.lesson_id,dr.code,dr.name_vi,dr.name_ja,
  dr.description,dr.voice_code
FROM dialogue_role dr JOIN lesson l ON l.id=dr.lesson_id
JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=2
ON DUPLICATE KEY UPDATE id=VALUES(id);

  bubble_side,bubble_x,bubble_y)
SELECT 4000000+dld.content_item_id,
  CASE WHEN dld.dialogue_role_id IS NULL THEN NULL ELSE 4000000+dld.dialogue_role_id END,
  dld.scene_code,dld.bubble_side,dld.bubble_x,dld.bubble_y
FROM dialogue_line_detail dld JOIN content_item ci ON ci.id=dld.content_item_id
JOIN lesson_section ls ON ls.id=ci.section_id JOIN lesson l ON l.id=ls.lesson_id
JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=2
ON DUPLICATE KEY UPDATE content_item_id=VALUES(content_item_id);

SELECT 4000000+dlc.id,4000000+dlc.content_item_id,dlc.order_index,
  dlc.surface,dlc.meaning_vi
FROM dialogue_line_chunk dlc JOIN content_item ci ON ci.id=dlc.content_item_id
JOIN lesson_section ls ON ls.id=ci.section_id JOIN lesson l ON l.id=ls.lesson_id
JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=2
ON DUPLICATE KEY UPDATE id=VALUES(id);

  merged_url,start_ms,end_ms)
SELECT 4000000+ca.id,ca.owner_type,4000000+ca.owner_id,ca.voice_code,
  ca.audio_url,ca.merged_url,ca.start_ms,ca.end_ms
FROM content_audio ca JOIN content_item ci
  ON ca.owner_type='CONTENT_ITEM' AND ci.id=ca.owner_id
JOIN lesson_section ls ON ls.id=ci.section_id JOIN lesson l ON l.id=ls.lesson_id
JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=2
ON DUPLICATE KEY UPDATE id=VALUES(id);
COMMIT;

-- These are structural post-checks. Browser study, scoring, semantic audio
-- alignment, and Reading/Listening chapter composition require separate UAT.
SELECT t.id,t.source_code,t.status,t.is_learning_path_source,
  COUNT(DISTINCT l.id) AS lessons,COUNT(DISTINCT gp.id) AS grammar_points,
  COUNT(DISTINCT dld.content_item_id) AS dialogue_lines
FROM textbook t JOIN unit u ON u.textbook_id=t.id
JOIN lesson l ON l.unit_id=u.id
LEFT JOIN grammar_point gp ON gp.lesson_id=l.id
LEFT JOIN lesson_section ls ON ls.lesson_id=l.id
LEFT JOIN content_item ci ON ci.section_id=ls.id
LEFT JOIN dialogue_line_detail dld ON dld.content_item_id=ci.id
WHERE t.id=4000002
GROUP BY t.id,t.source_code,t.status,t.is_learning_path_source;
-- END sql/seeds/learning_owned_sekai_n4_core.sql

-- BEGIN sql/seeds/learning_owned_n4_kanji_smart_test.sql SHA256 758e0f41422dd6fe7cbd393487207d7b2566a819c654f0c4c3393a6e89a78ab1
-- [JLAS-W0108] Learning-owned N4 JLPT Kanji questions, from independently copied source rows.
-- Owner authorized using DRAFT source as main Learning content on 2026-10-15.
-- Preserve source-team rows. HOLD structurally invalid questions; do not retag old rows.
SET NAMES utf8mb4;
SET @owned_n4_tag = (SELECT knowledge_tag_id FROM assessment_question WHERE JSON_UNQUOTE(JSON_EXTRACT(context_json,'$.seed_key'))='KANJI-DIVERSE-N4-003' AND skill='KANJI' AND jlpt_level='N4' LIMIT 1);
DELIMITER $$
DROP PROCEDURE IF EXISTS jlas_assert_owned_n4_kanji$$
CREATE PROCEDURE jlas_assert_owned_n4_kanji()
BEGIN
  IF @owned_n4_tag IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing N4 Kanji knowledge tag'; END IF;
  IF EXISTS (SELECT 1 FROM assessment_question q WHERE BINARY q.source_code=BINARY CONVERT(X'4c502d4f574e45442d4a4c50542d4e342d4b414e4a492d524541442d303031' USING utf8mb4) AND NOT (BINARY q.question_text=BINARY CONVERT(X'e3808ce4baa4e9809ae3808de381aee8aaade381bfe696b9e381a8e38197e381a6e6ada3e38197e38184e38282e381aee38292e981b8e38293e381a7e3818fe381a0e38195e38184e38082' USING utf8mb4) AND BINARY q.answer_text=BINARY CONVERT(X'e38193e38186e381a4e38186' USING utf8mb4) AND BINARY q.option_1=BINARY CONVERT(X'e38193e38186e381a4e38186' USING utf8mb4) AND BINARY q.option_2=BINARY CONVERT(X'e38193e38186e381a4e38186e381b2' USING utf8mb4) AND BINARY q.option_3=BINARY CONVERT(X'e38193e38186e381a9e38186' USING utf8mb4) AND BINARY q.option_4=BINARY CONVERT(X'e38193e38186e38193e38186' USING utf8mb4) AND q.correct_option=1 AND q.skill='KANJI' AND q.jlpt_level='N4' AND q.is_active=1 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(q.context_json,'$.lexeme'))=BINARY CONVERT(X'e4baa4e9809a' USING utf8mb4) AND JSON_CONTAINS(JSON_EXTRACT(q.context_json,'$.additional_tags'),JSON_QUOTE('JLPT')))) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Existing owned N4 question differs';
  END IF;
  IF EXISTS (SELECT 1 FROM assessment_question q WHERE BINARY q.source_code=BINARY CONVERT(X'4c502d4f574e45442d4a4c50542d4e342d4b414e4a492d524541442d303032' USING utf8mb4) AND NOT (BINARY q.question_text=BINARY CONVERT(X'e3808ce5b7a5e5a0b4e3808de381aee8aaade381bfe696b9e381a8e38197e381a6e6ada3e38197e38184e38282e381aee38292e981b8e38293e381a7e3818fe381a0e38195e38184e38082' USING utf8mb4) AND BINARY q.answer_text=BINARY CONVERT(X'e38193e38186e38198e38287e38186' USING utf8mb4) AND BINARY q.option_1=BINARY CONVERT(X'e381b2e38193e38186e38198e38287e38186' USING utf8mb4) AND BINARY q.option_2=BINARY CONVERT(X'e38193e38186e38198e38287e38186' USING utf8mb4) AND BINARY q.option_3=BINARY CONVERT(X'e38193e38186e381a1e38287e38186' USING utf8mb4) AND BINARY q.option_4=BINARY CONVERT(X'e38193e38186e3818ee38287e38186' USING utf8mb4) AND q.correct_option=2 AND q.skill='KANJI' AND q.jlpt_level='N4' AND q.is_active=1 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(q.context_json,'$.lexeme'))=BINARY CONVERT(X'e5b7a5e5a0b4' USING utf8mb4) AND JSON_CONTAINS(JSON_EXTRACT(q.context_json,'$.additional_tags'),JSON_QUOTE('JLPT')))) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Existing owned N4 question differs';
  END IF;
  IF EXISTS (SELECT 1 FROM assessment_question q WHERE BINARY q.source_code=BINARY CONVERT(X'4c502d4f574e45442d4a4c50542d4e342d4b414e4a492d524541442d303033' USING utf8mb4) AND NOT (BINARY q.question_text=BINARY CONVERT(X'e3808ce69687e6b395e3808de381aee8aaade381bfe696b9e381a8e38197e381a6e6ada3e38197e38184e38282e381aee38292e981b8e38293e381a7e3818fe381a0e38195e38184e38082' USING utf8mb4) AND BINARY q.answer_text=BINARY CONVERT(X'e381b6e38293e381bde38186' USING utf8mb4) AND BINARY q.option_1=BINARY CONVERT(X'e3818ee38293e38193e38186' USING utf8mb4) AND BINARY q.option_2=BINARY CONVERT(X'e38186e38293e381a9e38186' USING utf8mb4) AND BINARY q.option_3=BINARY CONVERT(X'e381b6e38293e381bde38186' USING utf8mb4) AND BINARY q.option_4=BINARY CONVERT(X'e38195e38293e381bd' USING utf8mb4) AND q.correct_option=3 AND q.skill='KANJI' AND q.jlpt_level='N4' AND q.is_active=1 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(q.context_json,'$.lexeme'))=BINARY CONVERT(X'e69687e6b395' USING utf8mb4) AND JSON_CONTAINS(JSON_EXTRACT(q.context_json,'$.additional_tags'),JSON_QUOTE('JLPT')))) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Existing owned N4 question differs';
  END IF;
  IF EXISTS (SELECT 1 FROM assessment_question q WHERE BINARY q.source_code=BINARY CONVERT(X'4c502d4f574e45442d4a4c50542d4e342d4b414e4a492d524541442d303034' USING utf8mb4) AND NOT (BINARY q.question_text=BINARY CONVERT(X'e3808ce799bae99fb3e3808de381aee8aaade381bfe696b9e381a8e38197e381a6e6ada3e38197e38184e38282e381aee38292e981b8e38293e381a7e3818fe381a0e38195e38184e38082' USING utf8mb4) AND BINARY q.answer_text=BINARY CONVERT(X'e381afe381a4e3818ae38293' USING utf8mb4) AND BINARY q.option_1=BINARY CONVERT(X'e38197e381a4e38282e38293' USING utf8mb4) AND BINARY q.option_2=BINARY CONVERT(X'e381afe38284e3818ae3818d' USING utf8mb4) AND BINARY q.option_3=BINARY CONVERT(X'e381afe38293e381b6e38293' USING utf8mb4) AND BINARY q.option_4=BINARY CONVERT(X'e381afe381a4e3818ae38293' USING utf8mb4) AND q.correct_option=4 AND q.skill='KANJI' AND q.jlpt_level='N4' AND q.is_active=1 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(q.context_json,'$.lexeme'))=BINARY CONVERT(X'e799bae99fb3' USING utf8mb4) AND JSON_CONTAINS(JSON_EXTRACT(q.context_json,'$.additional_tags'),JSON_QUOTE('JLPT')))) THEN
