-- BEGIN data/learning-owned/learning-content.json#sections.jlas_compiled_book_n4 SHA256 4ab4e65cf9a84c8b6a870d4ffca35ae52829fcaf20ee15e89c8989ef66628cc4
-- [JLAS-W0108] D3-04 (owner 2026-10-24): J-LAS N4 compiled book — every book of the level merged per skill,
-- deduplicated, easy → hard. Learning-owned rows only; source books, dictionary entries and Kanji are read, never changed
-- (a word missing from the dictionary is added as a DRAFT textbook entry). Generated: do not hand-edit.
DELIMITER $$
DROP PROCEDURE IF EXISTS jlas_assert_compiled_n4$$
CREATE PROCEDURE jlas_assert_compiled_n4()
BEGIN
  IF EXISTS (SELECT 1 FROM textbook WHERE id=6000000000 AND source_code<>'LP-OWNED-JLAS-N4-COMPILED') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Compiled N4 textbook id collision';
  END IF;
  IF (SELECT COUNT(*) FROM lesson l JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=4000002
      AND l.lesson_type='CURRICULUM') <> 25 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Dialogue source book of N4 changed its chapter count';
  END IF;
END$$
DELIMITER ;
CALL jlas_assert_compiled_n4();
DROP PROCEDURE jlas_assert_compiled_n4;
DROP TEMPORARY TABLE IF EXISTS jlas_compiled_word_n4;
DROP TEMPORARY TABLE IF EXISTS jlas_compiled_variant_n4;
CREATE TEMPORARY TABLE jlas_compiled_word_n4 (item_id BIGINT NOT NULL PRIMARY KEY, section_id BIGINT NOT NULL, order_index INT NOT NULL, expression VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL, reading VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL, normalized_expression VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL, normalized_reading VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL, meaning TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL, example_ja TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, example_vi TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, vocab_id BIGINT UNSIGNED);
CREATE TEMPORARY TABLE jlas_compiled_variant_n4 (item_id BIGINT NOT NULL, rank_no INT NOT NULL, normalized_expression VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL, normalized_reading VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL, PRIMARY KEY (item_id, rank_no));
START TRANSACTION;
SET @compiled_n4_tag=(SELECT id FROM tag WHERE code='LP-OWNED-JLAS-N4-COMPILED' LIMIT 1);
UPDATE content_item SET section_id=6000029999,order_index=1000000+(id-6100000000) WHERE id BETWEEN 6100000000 AND 6199999999 AND section_id IN (SELECT s.id FROM lesson_section s JOIN lesson l ON l.id=s.lesson_id JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=6000000000);
UPDATE grammar_point SET lesson_id=6000002999,order_index=1000000+(id-6200000000) WHERE id BETWEEN 6200000000 AND 6299999999 AND lesson_id IN (SELECT l.id FROM lesson l JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=6000000000);
UPDATE lesson_kanji SET lesson_id=6000002999 WHERE id BETWEEN 6300000000 AND 6399999999 AND lesson_id IN (SELECT l.id FROM lesson l JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=6000000000);
UPDATE jlas_compiled_word_n4 w SET w.vocab_id=(SELECT e.id FROM jlas_compiled_variant_n4 v JOIN vocabulary_entry e ON e.normalized_expression=v.normalized_expression AND e.normalized_reading=v.normalized_reading WHERE v.item_id=w.item_id ORDER BY v.rank_no LIMIT 1) WHERE w.item_id>0;
DELETE cv FROM content_vocabulary cv JOIN jlas_compiled_word_n4 w ON w.item_id=cv.content_item_id WHERE cv.vocabulary_id<>w.vocab_id;
SET @dialogue_src_n4=(SELECT l.id FROM lesson l JOIN unit u ON u.id=l.unit_id WHERE u.textbook_id=4000002 AND l.lesson_type='CURRICULUM' AND (u.order_index-1)*5+l.order_index=1 LIMIT 1);
